args.content:
import { ViewTransition } from 'react'

/**
 * The shared element that morphs between the grid thumbnail and the detail hero.
 *
 * The morph only happens when both call sites render the identical `name`, so
 * both of them go through this component rather than repeating the props.
 *
 * `share="morph"` puts the `morph` view-transition-class on the transition so
 * globals.css can target it. `default="none"` stops the image from running its
 * own crossfade during unrelated transitions (the directional page slide, the
 * Suspense reveal) — and per the React docs the explicit `share` is required
 * alongside `default="none"`, or the pair silently stops morphing.
 */
export function ProductImage({
  slug,
  color,
  className,
}: {
  slug: string
  color: string
  className: string
}) {
  return (
    <ViewTransition name={`product-image-${slug}`} share="morph" default="none">
      <div className={className} style={{ backgroundColor: color }} />
    </ViewTransition>
  )
}

