args.content:
import { ViewTransition } from 'react'
import type { ReactNode, ViewTransitionClassPerType } from 'react'

/**
 * Maps the transition types that our `<Link>`s tag navigations with onto the
 * matching CSS classes in globals.css.
 *
 * `default: 'none'` means any navigation *without* one of these types — browser
 * back/forward, `router.refresh()`, a Suspense reveal — produces no directional
 * animation, which is what we want: direction is a claim about history, and we
 * only know it for links we tagged ourselves.
 */
const directional: ViewTransitionClassPerType = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

/**
 * Slides a whole page in/out horizontally on tagged navigations.
 *
 * Render this inside each `page.tsx`, never in a layout: layouts persist across
 * navigations, so a wrapper there never mounts or unmounts and its enter/exit
 * animations would never fire.
 *
 * `name` must differ per route. Two `<ViewTransition>`s that share a name are
 * treated as one element moving, which would morph the pages into each other
 * instead of sliding one out and the other in.
 */
export function PageTransition({
  name,
  children,
}: {
  name: string
  children: ReactNode
}) {
  return (
    <ViewTransition
      name={name}
      enter={directional}
      exit={directional}
      default="none"
    >
      {children}
    </ViewTransition>
  )
}

