          href={`/product/${product.slug}`}
          className="product-card"
          // Going into a product is "forward" in this app's hierarchy, so the
          // content should slide left. See PageTransition.
          transitionTypes={['nav-forward']}
        >
          <ProductImage
            slug={product.slug}
            color={product.color}
