@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ─────────────────────────── View transitions ───────────────────────────
   Timings are shared across all three patterns so the app reads as one
   system. Exits are fast so old content stops competing for attention;
   enters are slower and start once the exit has finished. */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay swallows pointer events by default, so clicks during
   an animation are lost. Let them through to the live page underneath. */
::view-transition {
  pointer-events: none;
}

/* ── Shared element: thumbnail ⇄ detail hero ──
   The group animation is the morph itself — the browser interpolates position
   and size between the two. The blur mid-flight hides the artifacts of that
   interpolation. */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}
@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* ── Suspense reveal: skeleton hands off to content ──
   Vertical direction encodes hierarchy: the placeholder drops away, the real
   thing rises into its place. */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}
@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

/* ── Directional navigation ──
   Horizontal direction encodes history: forward moves content left, back moves
   it right. 60px is enough to read as direction without the user having to
   track something across the viewport. */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* ── Reduced motion ──
   Directional slides are the biggest motion-sensitivity trigger here, so all
   positional and geometric movement is removed: groups and image pairs snap
   straight to their final state. A short opacity-only crossfade is kept so the
   swap still reads as a transition rather than a jump cut, and the infinite
   skeleton pulse is stilled.

   For a hard cut instead, drop the two crossfade rules and give
   ::view-transition-old(*)/new(*) `animation-duration: 0s !important` too. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }

  ::view-transition-old(*) {
    animation: 120ms linear both reduced-fade-out !important;
  }
  ::view-transition-new(*) {
    animation: 120ms linear both reduced-fade-in !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

@keyframes reduced-fade-out {
  to {
    opacity: 0;
  }
}
@keyframes reduced-fade-in {
  from {
    opacity: 0;
  }
}

